 gen(a,t,rnd=Math.random){const E=[],n=a.length,checks=binaryRun(a,t).checks;
  E.push({line:-1,node:'start',note:L(`Search for ${t} in a list of ${n} items by halving the range.`,`Busca ${t} en una lista de ${n} elementos partiendo el rango a la mitad.`),ask:shuffle({q:L('Before you start: how many times will a[mid] be compared with the target?','Antes de empezar: ¿cuántas veces se comparará a[mid] con el número buscado?'),options:nums(uniq([checks,n,Math.ceil(n/2),1])),answer:0,why:L(`Each comparison throws away about half of what is left, so ${checks} ${pl(checks,'comparison is','comparisons are')} enough for ${n} items.`,`Cada comparación descarta cerca de la mitad de lo que queda, así que ${pl(checks,'basta 1 comparación',`bastan ${checks} comparaciones`)} para ${n} elementos.`)},rnd)});
  let low=0,high=n-1;const dim=()=>a.map((_,i)=>i).filter(i=>i<low||i>high);
  E.push({line:0,node:'init',chip:L(`low = 0, high = ${high}`,`low = 0, high = ${high}`),note:L(`The target could be anywhere: <b>low = 0</b>, <b>high = ${high}</b>.`,`El número podría estar en cualquier lugar: <b>low = 0</b>, <b>high = ${high}</b>.`),ptr:{low,high}});
  for(;;){const go=low<=high,left=high-low+1;
   E.push({line:1,node:'check',chip:go?L(`${left} left`,`${pl(left,'queda 1','quedan '+left)}`):L('nothing left','no queda nada'),note:go?L(`Is low = ${low} ≤ high = ${high}? Yes: ${pl(left,'1 item','the '+left+' items')} from ${low} to ${high} can still hold ${t}.`,`¿low = ${low} ≤ high = ${high}? Sí: ${pl(left,'1 elemento','los '+left+' elementos')} de ${low} a ${high} todavía ${pl(left,'puede','pueden')} contener ${t}.`):L(`Is low = ${low} ≤ high = ${high}? No: no item is left to check.`,`¿low = ${low} ≤ high = ${high}? No: ya no queda ningún elemento por revisar.`),ptr:go?{low,high}:{},dim:dim()});
   if(!go)break;const mid=Math.floor((low+high)/2),half=(low+high)/2;
   E.push({line:2,node:'mid',chip:L(`mid = ${mid}`,`mid = ${mid}`),note:L(`mid = ⌊(${low} + ${high}) / 2⌋ = <b>${mid}</b>.`,`mid = ⌊(${low} + ${high}) / 2⌋ = <b>${mid}</b>.`),ptr:{low,mid,high},dim:dim(),ask:shuffle({q:L(`low = ${low} and high = ${high}. What is mid?`,`low = ${low} y high = ${high}. ¿Cuánto vale mid?`),options:nums(uniq([mid,mid+1,low+high])),answer:0,why:L(`(${low} + ${high}) / 2 = ${half}${Number.isInteger(half)?'':', rounded down to '+mid}.`,`(${low} + ${high}) / 2 = ${half}${Number.isInteger(half)?'':', que se redondea hacia abajo a '+mid}.`)},rnd)});
   const eq=a[mid]===t,lt=a[mid]<t,act=eq?L('found','encontrado'):lt?L('right half','mitad derecha'):L('left half','mitad izquierda');
   E.push({line:3,node:'eq',chip:L(`${a[mid]} = ${t}? ${eq?'yes':'no'}`,`${a[mid]} = ${t}? ${eq?'sí':'no'}`),note:L(`Is a[${mid}] = ${a[mid]} equal to ${t}? <b>${eq?'Yes':'No'}</b>.`,`¿a[${mid}] = ${a[mid]} es igual a ${t}? <b>${eq?'Sí':'No'}</b>.`),cmp:[mid],ptr:{low,mid,high},dim:dim(),row:[low,high,mid,a[mid],act]});
   if(eq){E.push({line:3,node:'found',note:L(`Return <b>${mid}</b>: ${t} is at position ${mid}.`,`Devuelve <b>${mid}</b>: ${t} está en la posición ${mid}.`),hit:[mid],ptr:{mid},dim:dim(),done:true});return E;}
   E.push({line:4,node:'lt',chip:L(`${a[mid]} < ${t}? ${lt?'yes':'no'}`,`${a[mid]} < ${t}? ${lt?'sí':'no'}`),note:lt?L(`a[${mid}] = ${a[mid]} is smaller than ${t}, so ${t} can only be to the right of mid.`,`a[${mid}] = ${a[mid]} es menor que ${t}, así que ${t} solo puede estar a la derecha de mid.`):L(`a[${mid}] = ${a[mid]} is bigger than ${t}, so ${t} can only be to the left of mid.`,`a[${mid}] = ${a[mid]} es mayor que ${t}, así que ${t} solo puede estar a la izquierda de mid.`),cmp:[mid],ptr:{low,mid,high},dim:dim(),
    ask:{q:L(`a[${mid}] = ${a[mid]} is not ${t}. Where can ${t} still be?`,`a[${mid}] = ${a[mid]} no es ${t}. ¿Dónde puede estar todavía ${t}?`),options:L(['Right of mid','Left of mid'],['A la derecha de mid','A la izquierda de mid']),answer:lt?0:1,why:lt?L(`In a sorted list, everything left of mid is at most ${a[mid]}, which is smaller than ${t}.`,`En una lista ordenada, todo lo que está a la izquierda de mid es a lo más ${a[mid]}, que es menor que ${t}.`):L(`In a sorted list, everything right of mid is at least ${a[mid]}, which is bigger than ${t}.`,`En una lista ordenada, todo lo que está a la derecha de mid es al menos ${a[mid]}, que es mayor que ${t}.`)}});
   if(lt){low=mid+1;E.push({line:4,node:'lo',chip:L(`low = ${low}`,`low = ${low}`),note:L(`Discard mid and everything left of it: <b>low = ${low}</b>.`,`Descarta mid y todo lo que está a su izquierda: <b>low = ${low}</b>.`),ptr:{low,high},dim:dim()});}
   else{high=mid-1;E.push({line:5,node:'hi',chip:L(`high = ${high}`,`high = ${high}`),note:L(`Discard mid and everything right of it: <b>high = ${high}</b>.`,`Descarta mid y todo lo que está a su derecha: <b>high = ${high}</b>.`),ptr:{low,high},dim:dim()});}}
  E.push({line:6,node:'notfound',note:L(`Return <b>−1</b>: ${t} is not in the list. Comparisons made: ${checks}.`,`Devuelve <b>−1</b>: ${t} no está en la lista. Comparaciones hechas: ${checks}.`),dim:a.map((_,i)=>i),done:true});return E;}
