   if(isGoal){const path=pathTo(parent,c);E.push({line:3,node:'found',note:L(`Follow the parents back from G: a path of <b>${path.length-1} steps</b>. No path is shorter, because BFS reaches every cell first by a shortest route.`,`Sigue los padres de regreso desde G: un camino de <b>${path.length-1} pasos</b>. Ninguno es más corto, porque BFS llega a cada celda primero por una ruta más corta.`),...view({current:c,path}),done:true});return E;}
