/* ---------------- Complexity questions ---------------- */
const CPLX={
 'find-max':{q:L('How many comparisons a[i] > best does find-the-maximum make on a list of 1,000 items?','¿Cuántas veces compara a[i] > best el algoritmo para encontrar el máximo en una lista de 1,000 elementos?'),options:L(['10','500','999','1,000,000'],['10','500','999','1,000,000']),answer:2,why:L('Every item after the first is compared once: 1,000 − 1 = 999. The work grows in step with n.','Cada elemento después del primero se compara una vez: 1,000 − 1 = 999. El trabajo crece al mismo ritmo que n.')},
 'linear-search':{q:L('Linear search on 1,000,000 items: how many checks in the worst case?','Búsqueda lineal en 1,000,000 elementos: ¿cuántas revisiones en el peor caso?'),options:L(['20','1,000','500,000','1,000,000'],['20','1,000','500,000','1,000,000']),answer:3,why:L('In the worst case the target is last or missing, so every item is checked.','En el peor caso el número está al final o no está, así que se revisan todos los elementos.')},
 'bubble-sort':{q:L('Bubble sort with early stopping, on 100 items: how many comparisons in the worst case?','Ordenamiento burbuja con parada anticipada, en 100 elementos: ¿cuántas comparaciones en el peor caso?'),options:L(['99','664','4,950','10,000'],['99','664','4,950','10,000']),answer:2,why:L('A reversed list needs every pass: 99 + 98 + … + 1 = 4,950. Early stopping helps only when passes run out of swaps early.','Una lista invertida necesita todas las pasadas: 99 + 98 + … + 1 = 4,950. Parar antes solo ayuda cuando las pasadas se quedan pronto sin intercambios.')},
 'insertion-sort':{q:L('Insertion sort on a list of 1,000 items that is already sorted: how many comparisons?','Ordenamiento por inserción en una lista de 1,000 elementos ya ordenada: ¿cuántas comparaciones?'),options:L(['999','1,000','499,500','1,000,000'],['999','1,000','499,500','1,000,000']),answer:0,why:L('Each new item is compared once with the item before it, finds it smaller, and stays: 999 comparisons. Bubble sort would still make 499,500.','Cada elemento nuevo se compara una vez con el anterior, lo encuentra menor y se queda: 999 comparaciones. El ordenamiento burbuja haría 499,500 de todos modos.')},
 'binary-search':{q:L('Binary search on 1,000,000 sorted items: at most how many comparisons?','Búsqueda binaria en 1,000,000 de elementos ordenados: ¿cuántas comparaciones como máximo?'),options:L(['20','1,000','500,000','1,000,000'],['20','1,000','500,000','1,000,000']),answer:0,why:L('Each comparison halves what is left. Twenty halvings shrink 1,000,000 items to nothing, because 2²⁰ = 1,048,576.','Cada comparación parte a la mitad lo que queda. Veinte mitades reducen 1,000,000 de elementos a nada, porque 2²⁰ = 1,048,576.')},
 'merge-sort':{q:L('Merge sort on 1,024 items: at most how many comparisons?','Ordenamiento por mezcla con 1,024 elementos: ¿cuántas comparaciones como máximo?'),options:L(['1,023','9,217','523,776','1,048,576'],['1,023','9,217','523,776','1,048,576']),answer:1,why:L('There are 10 rounds of merging, because 2¹⁰ = 1,024. Each merge makes at most one comparison fewer than the items it merges, so a round makes at most 1,024 minus its number of merges. In all: 10 × 1,024 − 1,023 = 9,217. Insertion sort can need 523,776.','Hay 10 rondas de mezcla, porque 2¹⁰ = 1,024. Cada mezcla hace a lo más una comparación menos que los elementos que mezcla, así que una ronda hace a lo más 1,024 menos su número de mezclas. En total: 10 × 1,024 − 1,023 = 9,217. El ordenamiento por inserción puede necesitar 523,776.')},
 hanoi:{q:L('How many moves does the Tower of Hanoi need for 20 disks?','¿Cuántos movimientos necesita la torre de Hanói con 20 discos?'),options:L(['40','400','1,048,575','20,000,000'],['40','400','1,048,575','20,000,000']),answer:2,why:L('Each extra disk doubles the moves and adds one, so 20 disks need 2²⁰ − 1 = 1,048,575 moves. At one move per second, that is about 12 days.','Cada disco extra duplica los movimientos y suma uno, así que 20 discos necesitan 2²⁰ − 1 = 1,048,575 movimientos. A un movimiento por segundo, son unos 12 días.')},
 bfs:{q:L('In an open grid of 1,000 × 1,000 cells, at most how many cells can BFS mark?','En una cuadrícula abierta de 1,000 × 1,000 celdas, ¿cuántas celdas puede marcar BFS como máximo?'),options:L(['2,000','1,000,000','4,000,000','1,000,000,000,000'],['2,000','1,000,000','4,000,000','1,000,000,000,000']),answer:1,why:L('Each cell is marked at most once, so at most 1,000,000. Each cell taken looks at 4 neighbours, so there are at most 4,000,000 neighbour checks: the work grows in step with the number of cells.','Cada celda se marca a lo más una vez, así que a lo más 1,000,000. Cada celda tomada mira 4 vecinos, así que hay a lo más 4,000,000 de revisiones de vecinos: el trabajo crece al mismo ritmo que el número de celdas.')},
 dfs:{q:L('In this DFS a cell can be on the stack more than once. At most how many copies of one cell can be put on the stack?','En esta DFS una celda puede estar varias veces en la pila. ¿Cuántas copias de una celda pueden ponerse en la pila como máximo?'),options:L(['1','4','1,000','1,000,000'],['1','4','1,000','1,000,000']),answer:1,why:L('A copy is added only by a neighbour taken while the cell is still unmarked. A cell has at most 4 neighbours, so it gets at most 4 copies.','Una copia solo la agrega un vecino que se toma mientras la celda sigue sin marcar. Una celda tiene a lo más 4 vecinos, así que recibe a lo más 4 copias.')},
 'greedy-change':{q:L('Paying 1,000,000 cents with coins of 25, 10, 5 and 1, one subtraction at a time: how many subtractions?','Pagar 1,000,000 de centavos con monedas de 25, 10, 5 y 1, una resta a la vez: ¿cuántas restas?'),options:L(['4','40,000','1,000,000','25,000,000'],['4','40,000','1,000,000','25,000,000']),answer:1,why:L('1,000,000 = 40,000 × 25, so the greedy method takes 40,000 coins of 25, one subtraction each. Dividing instead needs one step per kind of coin: 4.','1,000,000 = 40,000 × 25, así que el método voraz toma 40,000 monedas de 25, una resta por cada una. Dividiendo, basta un paso por tipo de moneda: 4.')},
 euclid:{q:L('For two numbers below 1,000,000, at most about how many remainder steps does Euclid’s algorithm need?','Para dos números menores que 1,000,000, ¿aproximadamente cuántos pasos con residuo necesita como máximo el algoritmo de Euclides?'),options:L(['about 30','about 1,000','about 500,000','about 1,000,000'],['unos 30','unos 1,000','unos 500,000','unos 1,000,000']),answer:0,why:L('Never more than 29. The worst pairs are neighbouring Fibonacci numbers: 832,040 and 514,229 take 28 steps, and one more if they are given in the other order.','Nunca más de 29. Los peores pares son números de Fibonacci consecutivos: 832,040 y 514,229 necesitan 28 pasos, y uno más si se dan en el orden contrario.')}};

